package com.lbos.commercecustomer.repository; import com.lbos.commercecustomer.entity.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param; public interface CustomerCartItemRepository extends JpaRepository<CustomerCartItem,UUID> {Optional<CustomerCartItem> findByCartId(UUID id); List<CustomerCartItem> findByCartCustomerId(UUID id); /** Cart lines with their cart and product in ONE query - the cart response reads both for every line, which the plain derived query above turned into 2 extra lazy selects per line. */ @Query("select i from CustomerCartItem i join fetch i.cart c join fetch c.product where c.customer.id=:customerId") List<CustomerCartItem> findWithCartAndProductByCartCustomerId(@Param("customerId") UUID customerId); Optional<CustomerCartItem> findByIdAndCartCustomerId(UUID id,UUID c); long deleteByCartCustomerId(UUID c);}